"""Styles for the change and number screens of Arrange mode, the Cheer Song menu pages, and the lettering, plates and windows of the arr_sub sprite file.

A style is a recipe that tells the lettering tool (pp15/art/typeset.py) how to draw an English label on a sprite sheet:
font, size, colours, outline, shadow.

Used by these spec files (specs/<name>.json, one per sprite file, each label names a style): chrsong, arr_sub, arr_chg, arr_num.
"""
import numpy as np
from pp15.art import typeset as ui_type
from .common import ringfill, flat

STYLES = {}


# ---- chrsong.arc, arr_chg.arc, arr_num.arc ---------------------------------------------------------------------------

def _win(style, c0, c1):
    def cut(ink, base):
        art, b = style(ink, base)
        out = art[:, c0:c1]
        if out.shape[1] == 0:
            out = np.zeros((art.shape[0], 1), np.uint8)
        return out, b
    return cut

def _sil(front, c):
    def style(ink, base):
        out, b = STYLES[front](ink, base)
        return np.where(out > 0, c, 0).astype(np.uint8), b
    return style

